mapper.select:
SELECT COUNT(member_id) AS CHECK_CNT	/*MemberMapper.selMemberCheck (회원가입 체크)*/	
  FROM MEMBER
 WHERE 1 = 1

   AND member_name  = #{memberName}


   AND member_id  = #{memberId}


   AND member_phone  = #{memberPhone}

SELECT member_id					/*MemberMapper.selMember (회원가입 아이디 찾기)*/	
     , member_password
     , member_name
     , member_email	
  FROM MEMBER
 WHERE 1 = 1

   AND member_name  = #{memberName}


   AND member_id  = #{memberId}


   AND member_phone  = #{memberPhone}

mapper.insert:
INSERT INTO MEMBER (	/*MemberMapper.insertMember (회원 등록)*/
      member_id
    , member_name
    , member_password
    , member_phone
    , member_email
    , business_number
    , ceo_name
    , company_name
    , company_phone
    , privacy_agree
    , privacy_agree_date
) VALUES (
      #{memberId}
    , #{memberName}
    , #{memberPassword}
    , #{memberPhone}
    , #{memberEmail}
    , #{businessNumber}
    , #{ceoName}
    , #{companyName}
    , #{companyPhone}
    , #{privacyAgree}
    , NOW()
)

mapper.update:
UPDATE MEMBER	/*MemberMapper.updMemberPw (회원 비밀번호 수정)*/

    	member_password = #{memberPassword},
    	updated_at = NOW()

WHERE member_id = #{memberId}

  	AND member_phone = #{memberPhone}
